import org.junit.Test;
import static org.junit.Assert.*;
import java.io.ByteArrayOutputStream;
import java.io.IOException;

public class TextNodeTest {

    @Test
    public void nodeName_EmptyTextNode_ReturnsNull() {
        TextNode node = new TextNode("");
        assertEquals(null, node.nodeName());
    }

    @Test
    public void nodeName_TextNode_ReturnsTextContent() {
        String text = "Hello World";
        TextNode node = new TextNode(text);
        assertEquals(text, node.nodeName());
    }

    @Test
    public void text_EmptyTextNode_ReturnsEmptyString() {
        TextNode node = new TextNode("");
        assertEquals("", node.text());
    }

    @Test
    public void text_TextNode_ReturnsTextContent() {
        String text = "Hello World";
        TextNode node = new TextNode(text);
        assertEquals(text, node.text());
    }

    @Test
    public void text replacement_TreeNode_replacesOldText() {
        String originalText = "Hello World";
        String newText = "New Text";
        TextNode node = new TextNode(originalText);
        node.text(newText);
        assertEquals(newText, node.text());
    }

    @Test
    public void getWholeText_EmptyTextNode_ReturnsEmptyString() {
        TextNode node = new TextNode("");
        assertEquals("", node.getWholeText());
    }

    @Test
    public void getWholeText_TextNode_ReturnsTextContent() {
        String text = "Hello World";
        TextNode node = new TextNode(text);
        assertEquals(text, node.getWholeText());
    }

    @Test
    public void isBlank_EmptyTextNode_ReturnsTrue() {
        TextNode node = new TextNode("");
        assertTrue(node.isBlank());
    }

    @Test
    public void isBlank_TextNode_withWhitespace_ReturnsFalse() {
        String text = "Hello World";
        TextNode node = new TextNode(text);
        assertFalse(node.isBlank());
    }

    @Test
    public void splitText_SplittingAtOffset_MatchesCorrectedText() {
        String text = "Hello World";
        int offset = 5;
        TextNode node = new TextNode(text);
        TextNode actualSplitNode = node.splitText(offset);
        assertEquals("World", actualSplitNode.text());
    }

    @Test
    public void splitText_SplittingAtOffset_RaisesIndexOutOfBoundsException() {
        String text = "Hello World";
        int offset = 10;
        try {
            new TextNode(text).splitText(offset);
            fail();
        } catch (ArrayIndexOutOfBoundsException e) {
            // expected
        }
    }

    @Test
    public void outerHtmlHead_AppendsToAccumulator() throws IOException {
        ByteArrayOutputStream outContent = new ByteArrayOutputStream();
        Appendable accum = outContent;
        TextNode node = new TextNode("<html><body>Hello World</body></html>");
        Document document = new Document(outContent);
        node.outerHtmlHead(accum, 0, document.getOutputSettings());
        String actualHTML = StringUtil.toString(document.getOutputSettings().getOutput());
        assertEquals("<html><body>Hello World</body></html>", actualHTML);
    }

    @Test
    public void outerHtmlTail_AppendsToAccumulator() throws IOException {
        ByteArrayOutputStream outContent = new ByteArrayOutputStream();
        Appendable accum = outContent;
        TextNode node = new TextNode("<html><body>Hello World</body></html>");
        Document document = new Document(outContent);
        node.outerHtmlTail(accum, 0, document.getOutputSettings());
        String actualHTML = StringUtil.toString(document.getOutputSettings().getOutput());
        assertEquals("<html><body>Hello World</body></html>", actualHTML);
    }

    @Test
    public void clone_SameText_ReturnsSameTextNode() {
        TextNode node = new TextNode("Hello World");
        TextNode cloned = node.clone();
        assertEquals(node, cloned);
    }

    @Test
    public void createFromEncoded_DecodedTextIsOriginalContent() throws IOException {
        String encodedText = "UTF-8Hello World";
        TextNode node = TextNode.createFromEncoded(encodedText);
        assertEquals("Hello World", node.text());
    }

    @Test
    public void normaliseWhitespace_AddsLeadingSpaces() {
        String text = "  Hello   World ";
        assertEquals("  Hello   World ", TextNode.normaliseWhitespace(text));
    }

    @Test
    public void stripLeadingWhitespace_RemovesLeadingSpaces() {
        String text = "  Hello   World ";
        assertEquals("Hello World", TextNode.stripLeadingWhitespace(text));
    }

    @Test
    public void lastCharIsWhitespace_EffectsOnlyLastCharacter() {
        StringBuilder sb = new StringBuilder();
        assertTrue(TextNode.lastCharIsWhitespace(sb));
        sb.deleteCharAt(sb.length() - 1);
        assertFalse(TextNode.lastCharIsWhitespace(sb));
    }
}
